class Solution {
public:
    int minimumSubarrayLength(vector<int>& nums, int k) {
        vector<int> bit_counts(32, 0);
        auto get_val = [&]() {
            int val = 0;
            for (int b = 0; b < 32; ++b) {
                if (bit_counts[b] > 0) val |= (1 << b);
            }
            return val;
        };

        int left = 0, ans = INT_MAX;
        for (int right = 0; right < nums.size(); ++right) {
            for (int b = 0; b < 32; ++b) {
                if ((nums[right] >> b) & 1) bit_counts[b]++;
            }
            while (left <= right && get_val() >= k) {
                ans = min(ans, right - left + 1);
                for (int b = 0; b < 32; ++b) {
                    if ((nums[left] >> b) & 1) bit_counts[b]--;
                }
                left++;
            }
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

class Solution {
    public int minimumSubarrayLength(int[] nums, int k) {
        int[] bitCounts = new int[32];
        int left = 0, ans = Integer.MAX_VALUE;
        for (int right = 0; right < nums.length; right++) {
            for (int b = 0; b < 32; b++) {
                if (((nums[right] >> b) & 1) == 1) bitCounts[b]++;
            }
            while (left <= right && getVal(bitCounts) >= k) {
                ans = Math.min(ans, right - left + 1);
                for (int b = 0; b < 32; b++) {
                    if (((nums[left] >> b) & 1) == 1) bitCounts[b]--;
                }
                left++;
            }
        }
        return ans == Integer.MAX_VALUE ? -1 : ans;
    }

    private int getVal(int[] bitCounts) {
        int val = 0;
        for (int b = 0; b < 32; b++) {
            if (bitCounts[b] > 0) val |= (1 << b);
        }
        return val;
    }
}

